<script setup lang="ts">
import {ref} from 'vue';import {onLoad,onShow} from '@dcloudio/uni-app';import {useI18n} from 'vue-i18n';import {api} from '@/api';import type {BrandChange} from '@/api/management-types';import {idempotencyKey} from '@shared/net/http-client';import {confirm} from '@ai-shop/ui/prompt';
const {t}=useI18n();const c=ref(''),reason=ref('');const row=ref<BrandChange|null>(null);const busy=ref(false),failed=ref(false);let key=idempotencyKey();
async function load(){try{row.value=await api.mBrandChange(c.value);failed.value=false}catch{failed.value=true}}
async function resume(){if(busy.value||!row.value)return;busy.value=true;try{await api.mSvFinancialBrandResume(c.value,{managementNo:row.value.managementNo});await load()}catch{failed.value=true}finally{busy.value=false}}
async function decide(decision:'APPROVE'|'REJECT'){if(busy.value||!row.value||!reason.value.trim())return;if(!await confirm({title:t(decision==='APPROVE'?'management.confirm':'management.reject'),danger:decision==='REJECT'}))return;busy.value=true;try{row.value=await api.mDecideBrandChange(c.value,{decision,expectedRevision:row.value.revision,reason:reason.value.trim()},key);key=idempotencyKey()}catch{failed.value=true}finally{busy.value=false}}
onLoad(q=>{c.value=q?.c||''});onShow(load);
</script>
<template><sh-scaffold title-key="management.brandChange"><view v-if="failed" class="sh-card" @tap="load">{{t('management.retry')}}</view><template v-if="row"><view class="sh-card"><text class="sh-chip">{{t('management.state.'+row.status)}}</text><view class="sh-cell">{{row.reason}}</view><view v-for="blocker in row.blockers" :key="blocker" class="txt-sub sh-muted">{{t('management.blocker.'+blocker)}}</view></view><view v-if="row.actions?.includes('brand.change.decide')" class="sh-card"><text class="field__label">{{t('management.reason')}}</text><textarea v-model="reason" class="field__area" maxlength="255"/></view><sh-actionbar v-if="row.actions?.includes('brand.financial.change.resume')"><view class="sh-btn" @tap="resume">{{t('svGov.retry')}}</view></sh-actionbar><sh-actionbar v-if="row.actions?.includes('brand.change.decide')"><view class="sh-row"><view class="sh-btn sh-btn--danger" @tap="decide('REJECT')">{{t('management.reject')}}</view><view class="sh-btn" @tap="decide('APPROVE')">{{t(busy?'management.loading':'management.confirm')}}</view></view></sh-actionbar></template></sh-scaffold></template>
